#define ED_VEC_COUNT (sizeof(ED_VECS) / sizeof(ED_VECS[0]))

/* ---------------- 用例 ---------------- */

/* L 的小端 16 位 limb 表，用例里用来构造 s + L。 */
static const uint32 ED_L16[16] =
{
    0xd3edu, 0x5cf5u, 0x631au, 0x5812u, 0x9cd6u, 0xa2f7u, 0xf9deu, 0x14deu,
    0x0000u, 0x0000u, 0x0000u, 0x0000u, 0x0000u, 0x0000u, 0x0000u, 0x1000u
};

/* s += L，就地按 16 位 limb 进位；向量里的 s 都远小于 L，加完仍在 256 位内。 */
static void add_l(uint8 s[32])
{
    uint32 carry = 0u;
    uint32 j;

    for(j = 0u; j < 16u; j++)
    {
        uint32 v = (uint32)s[j * 2u] | ((uint32)s[j * 2u + 1u] << 8);
        uint32 sum = v + ED_L16[j] + carry;
        s[j * 2u]      = (uint8)(sum & 0xFFu);
        s[j * 2u + 1u] = (uint8)((sum >> 8) & 0xFFu);
        carry = sum >> 16;
    }
}

int main(void)
{
    /* y = p 的非规范编码：解压必须拒绝，而不是把它归约成 0 再算。 */
    static const uint8 PK_P[32] =
    {
        0xed, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
        0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
        0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
        0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0x7f
    };
    uint8 sig[64];
    uint8 pk[32];
    uint8 msg[1024];
    uint32 i;

    for(i = 0u; i < (uint32)ED_VEC_COUNT; i++)
    {
        const ed_vec_t *v = &ED_VECS[i];

        check("valid", arkrtos_ed25519_verify(v->sig, v->msg, v->len, v->pk), 0);

        memcpy(sig, v->sig, 64u);
        sig[3] ^= 0x01u;
        check("flip R", arkrtos_ed25519_verify(sig, v->msg, v->len, v->pk), -1);

        memcpy(sig, v->sig, 64u);
        sig[40] ^= 0x01u;
        check("flip s", arkrtos_ed25519_verify(sig, v->msg, v->len, v->pk), -1);

        if(v->len != 0u)
        {
            memcpy(msg, v->msg, v->len);
            msg[v->len / 2u] ^= 0x01u;
            check("flip msg", arkrtos_ed25519_verify(v->sig, msg, v->len, v->pk), -1);
            check("short msg", arkrtos_ed25519_verify(v->sig, v->msg, v->len - 1u, v->pk), -1);
        }

        memcpy(pk, v->pk, 32u);
        pk[0] ^= 0x01u;
        check("wrong pk", arkrtos_ed25519_verify(v->sig, v->msg, v->len, pk), -1);

        check("pk y = p", arkrtos_ed25519_verify(v->sig, v->msg, v->len, PK_P), -1);

        memcpy(sig, v->sig, 64u);
        add_l(&sig[32]);
        check("s + L", arkrtos_ed25519_verify(sig, v->msg, v->len, v->pk), -1);
    }

    /* 空指针与长度不自洽：一律拒收，不靠调用方先判断。 */
    check("null sig", arkrtos_ed25519_verify(NULL, ED_VECS[0].msg, 0u, ED_VECS[0].pk), -1);
    check("null pk", arkrtos_ed25519_verify(ED_VECS[0].sig, ED_VECS[0].msg, 0u, NULL), -1);
    check("null msg with len", arkrtos_ed25519_verify(ED_VECS[4].sig, NULL, 32u, ED_VECS[4].pk), -1);

    if(g_fails == 0)
    {
        printf("ED25519-HOST OK (%d checks over %u vectors)\n", g_checks, (unsigned)ED_VEC_COUNT);
        return 0;
    }

    printf("ED25519-HOST FAIL %d of %d\n", g_fails, g_checks);
    return 1;
}

#else

int main(void)
{
    printf("ED25519-HOST OFF OK\n");
    return 0;
}

#endif /* ARKRTOS_USE_ED25519 == 1 */
